"""Original Spanish/English course source. L records are lesson-specific scenes.
No human-review approval is asserted. Derived JSON is rebuilt by the builder.
"""
COURSES = {'dance-team': {'title':'Dance Team','category':'Sports','emoji':'💃','partner':'a supportive dance coach or teammate'}, 'cosmetology': {'title':'Cosmetology: Hair & Nails','category':'Service','emoji':'💅','partner':'a salon client, classmate, or salon mentor'}}
LESSONS=[]
def L(course,stage,title,grammar,terms,phrases,story,goal,opening,verbs,partner=None):
 def pairs(text):
  return [dict(zip(('target','native'),p.strip().split('~',1))) for p in text.strip().split('|') if p.strip()]
 LESSONS.append(dict(course=course,stage=stage,title=title,grammarKey=grammar,terms=pairs(terms),phrases=pairs(phrases),story=pairs(story),goal=goal,opening=opening,verbs=verbs.split(','),partner=partner or COURSES[course]['partner']))

