# Compact scene authoring for Core: two useful lines are also practiced as phrases.
def C(course,title,grammar,terms,story,goal,opening,verbs,phrases=None,partner=None):
 pairs=[s.strip() for s in story.split('|') if s.strip()]
 L(course,'core',title,grammar,terms,phrases or '|'.join([pairs[0],pairs[-1]]),story,goal,opening,verbs,partner)

